import sys

def main():
    import sys
    n = int(sys.stdin.read().strip())
    board = [[''] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if (i + j) % 2 == 0:
                board[i][j] = 'W'
            else:
                board[i][j] = 'B'

    for row in board:
        print(''.join(row))

if __name__ == "__main__":
    main()
